const context = $('Build WU88 Classifier Context').first().json || {};
const catalog = Array.isArray(context.intent_catalog) ? context.intent_catalog : [];

function clean(v){ return String(v ?? '').trim(); }
function parseObject(v){
  if (v && typeof v === 'object' && !Array.isArray(v)) return v;
  let s=clean(v);
  if (!s) return {};
  s=s.replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/i,'').trim();
  try { const p=JSON.parse(s); return p && typeof p==='object' ? p : {}; } catch {}
  const a=s.indexOf('{'), b=s.lastIndexOf('}');
  if (a>=0 && b>a) { try { const p=JSON.parse(s.slice(a,b+1)); return p && typeof p==='object' ? p : {}; } catch {} }
  return {};
}
const raw=parseObject($json.output ?? $json.text ?? $json.response ?? $json);
const byName=new Map(catalog.map(r=>[clean(r.spm_intent_name),r]));
const primary=clean(raw.spm_intent);
const matched=byName.get(primary) || null;
let secondary=clean(raw.secondary_spm_intent);
if (!byName.has(secondary) || secondary===primary) secondary='';

let confidence=Number(raw.confidence);
if (!Number.isFinite(confidence)) confidence=0;
confidence=Math.max(0,Math.min(1,confidence));

let language=clean(raw.language).toLowerCase();
if (!['ar','en','fr'].includes(language)) {
  const msg=clean(context?.message?.raw);
  language=/[\u0600-\u06FF]/.test(msg) ? 'ar' : /\b(?:bonjour|merci|oui|non|je|vous|cours|prix)\b/i.test(msg) ? 'fr' : 'en';
}

const threshold=matched && Number.isFinite(Number(matched.min_confidence)) ? Number(matched.min_confidence) : 0.85;
const fallbackFloor=0.60;
let route='fallback';
if (matched && confidence >= threshold) route='direct';
else if (matched && confidence >= fallbackFloor) route='clarify';

const classification={
  schema:'SPM_CLASSIFIER_RESULT_V2',
  spm_intent:matched ? primary : '',
  secondary_spm_intent:secondary,
  confidence,
  threshold,
  ambiguous:route!=='direct',
  route_decision:route,
  requires_clarification:route==='clarify',
  allow_irreversible_action:route==='direct',
  language,
  rationale_code:clean(raw.rationale_code) || (matched ? 'MODEL_CLASSIFICATION' : 'INVALID_OR_MALFORMED_INTENT'),
  intent_id:matched?.intent_id ?? null,
  category:matched?.category ?? null,
  required_entities:Array.isArray(matched?.required_entities) ? matched.required_entities : [],
  legacy_route_intent:matched?.legacy_route_intent ?? null,
  legacy_next_action:matched?.legacy_next_action ?? null,
  risk_tier:matched?.risk_tier ?? null,
  source_gate:matched?.source_gate ?? null,
  sales_stage:matched?.sales_stage ?? null,
  catalog_version:'SPM_V2_62_INTENTS',
  catalog_count:catalog.length,
  model_output_valid:Boolean(matched),
  low_confidence_rule:route==='direct' ? 'NOT_TRIGGERED' : 'NO_IRREVERSIBLE_ACTION'
};

const state=context.sales_state || {};
state.classifier={
  ...(state.classifier||{}),
  spm_intent:classification.spm_intent || null,
  secondary_spm_intent:classification.secondary_spm_intent || null,
  confidence:classification.confidence,
  threshold:classification.threshold,
  ambiguous:classification.ambiguous,
  source_gate:classification.source_gate,
  risk_tier:classification.risk_tier,
  sales_stage:classification.sales_stage
};

return [{json:{...context,sales_state:state,classification}}];

const j=$input.first().json || {};
const c=j.classification || {};
const direct=c.route_decision==='direct' && c.model_output_valid===true && c.ambiguous===false;
const guard={
 schema:'SPM_CLASSIFIER_GUARD_V1',
 route_decision:c.route_decision || 'fallback',
 direct,
 allow_irreversible_action:Boolean(direct),
 block_reason:direct ? null : (c.route_decision==='clarify' ? 'LOW_CONFIDENCE_OR_AMBIGUOUS' : 'CLASSIFIER_FALLBACK'),
