};
if (j.sales_state?.classifier) j.sales_state.classifier.ambiguous=!direct;
return [{json:{...j,classifier_guard:guard}}];

const base=$('Apply Confidence + Ambiguity Guard').first().json || {};
const rows=$input.all().map(i=>i.json||{});
const active=rows.filter(r=>String(r.status??'').trim().toUpperCase()==='ACTIVE').map(r=>({
 entity_name:String(r.entity_name??'').trim(),
 data_type:String(r.data_type??'').trim(),
 sensitivity:String(r.sensitivity??'').trim(),
 source_of_truth:String(r.source_of_truth??'').trim(),
