})).filter(r=>r.entity_name);
const unique=new Set(active.map(r=>r.entity_name));
const ready=active.length===47 && unique.size===47;
return [{json:{...base,entity_contract:{
 schema:'SPM_ENTITY_OUTPUT_V2',
 expected_schema_rows:47,
 raw_preservation:true,
 output_record:['entity','raw','canonical','confidence','source','status','sensitivity','is_correction'],
 multi_student:'students[] are separate profiles and must never be collapsed',
 correction_precedence:'latest explicit customer correction wins unless live/system source owns final truth',
 timezone_rule:'never infer timezone from country alone',
 pii_rule:'exclude PII values from telemetry and aggressive correction'
},entity_schema:active,entity_schema_ready:ready,entity_schema_count:active.length}}];

const base=$('Build WU89 Entity Schema Context').first().json || {};
const rules=$input.all().map(i=>i.json||{}).filter(r=>String(r.status??'').trim().toUpperCase()==='ACTIVE').map(r=>({
 rule_id:String(r.rule_id??'').trim(),language:String(r.language??'').trim(),area:String(r.area??'').trim(),
 raw_pattern_or_example:String(r.raw_pattern_or_example??'').trim(),normalized_or_action:String(r.normalized_or_action??'').trim(),
 safety_rule:String(r.safety_rule??'').trim()
})).filter(r=>r.rule_id);
const ready=rules.length===29 && new Set(rules.map(r=>r.rule_id)).size===29;
const schema=(base.entity_schema||[]).map(r=>({entity:r.entity_name,type:r.data_type,sensitivity:r.sensitivity,validation:r.validation_rule}));
return [{json:{...base,normalization_rules:rules,normalization_ready:ready,normalization_count:rules.length,
 entity_schema_text:JSON.stringify(schema),
