const context=$('Build WU89 Extraction Context').first().json || {};
const schemaRows=Array.isArray(context.entity_schema)?context.entity_schema:[];
const schema=new Map(schemaRows.map(r=>[String(r.entity_name||'').trim(),r]));
const msg=String(context?.message?.raw??'').trim();

function clean(v){return String(v??'').trim();}
function parseObj(v){
 if(v&&typeof v==='object'&&!Array.isArray(v)) return v;
 let s=clean(v).replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/i,'').trim();
 if(!s)return {};
 try{return JSON.parse(s)}catch{}
 const a=s.indexOf('{'),b=s.lastIndexOf('}');
 if(a>=0&&b>a){try{return JSON.parse(s.slice(a,b+1))}catch{}}
 return {};
}
function arabicDigits(s){return s.replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d));}
function searchNorm(s){
 return arabicDigits(clean(s)).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'')
 .replace(/[\u064B-\u065F\u0670\u0640]/g,'').replace(/[إأآٱ]/g,'ا').replace(/ى/g,'ي').replace(/\s+/g,' ').trim();
}
function normSubject(v){
 const s=searchNorm(v);
 if(/^(math|maths|mathematics|رياضيات|ماث)$/.test(s)) return 'Math';
 if(/^(english|انجليزي|الانجليزيه|الانجليزية|اللغه الانجليزيه|اللغة الانجليزية)$/.test(s)) return 'English';
 if(/^(french|فرنسي|الفرنسيه|الفرنسية|اللغه الفرنسيه|اللغة الفرنسية)$/.test(s)) return 'French';
 if(/^(science|علوم|العلوم)$/.test(s)) return 'Science';
 if(/^(physics|فيزياء|الفيزياء)$/.test(s)) return 'Physics';
 if(/^(chemistry|كيمياء|الكيمياء)$/.test(s)) return 'Chemistry';
 if(/^(arabic|عربي|العربيه|العربية|اللغه العربيه|اللغة العربية)$/.test(s)) return 'Arabic';
 return clean(v);
}
function normGrade(v){
 let s=searchNorm(v).replace(/\b(?:grade|gr|g)\s*/g,'').replace(/الصف\s*/g,'').trim();
 const words={'عاشر':'10','العاشر':'10','تاسع':'9','التاسع':'9','ثامن':'8','الثامن':'8','سابع':'7','السابع':'7','سادس':'6','السادس':'6','خامس':'5','الخامس':'5','رابع':'4','الرابع':'4','ثالث':'3','الثالث':'3','ثاني':'2','الثاني':'2','اول':'1','الأول':'1'};
 if(words[s])s=words[s];
 const m=s.match(/\b(1[0-2]|[1-9])\b/);
 return m?`Grade ${m[1]}`:clean(v);
}
function normCountry(v){
 const s=searchNorm(v);
 if(['canada','كندا'].includes(s))return 'Canada';
 if(['usa','us','u.s.','united states','united states of america','america','امريكا','الولايات المتحده','الولايات المتحدة'].includes(s))return 'United States';
 return clean(v);
}
function normLang(v){
 const s=searchNorm(v);
 if(/arabic|عربي/.test(s))return 'Arabic';
 if(/english|انجليزي/.test(s))return 'English';
 if(/french|فرنسي/.test(s))return 'French';
 return clean(v);
}
function normalize(name,raw){
 if(['parent_name','student_name','transaction_reference','lesson_id','booking_id','lead_id','student_id','teacher_id'].includes(name))return clean(raw);
 if(name==='email')return clean(raw).toLowerCase();
 if(name==='phone')return clean(raw).replace(/[^\d+]/g,'');
 if(name==='subject')return normSubject(raw);
 if(name==='subjects')return Array.isArray(raw)?raw.map(normSubject):[normSubject(raw)];
 if(name==='grade')return normGrade(raw);
 if(name==='grades')return Array.isArray(raw)?raw.map(normGrade):[normGrade(raw)];
 if(name==='country')return normCountry(raw);
 if(['preferred_language','teaching_language'].includes(name))return normLang(raw);
 if(name==='number_of_students'){const n=Number(arabicDigits(clean(raw)).match(/\d+/)?.[0]);return Number.isFinite(n)&&n>0?n:clean(raw);}
 if(name==='timezone'){const s=clean(raw);return /^(?:America|Canada|Europe|Asia|Africa)\/[A-Za-z0-9_+\-]+$/.test(s)?s:s;}
 return clean(raw);
}
function validStatus(name,canonical,row){
 if(!canonical && canonical!==0)return 'rejected';
 if(name==='email')return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(canonical))?'valid':'needs_validation';
 if(name==='phone')return /^\+?\d{7,15}$/.test(String(canonical))?'valid':'needs_validation';
 if(name==='timezone')return /^(?:America|Canada|Europe|Asia|Africa)\/[A-Za-z0-9_+\-]+$/.test(String(canonical))?'valid':'needs_validation';
 if(['booking_id','lesson_id','transaction_reference','payment_status','lesson_status','lead_id','student_id','teacher_id'].includes(name))return 'needs_validation';
 return 'valid';
}

const raw=parseObj($json.output??$json.text??$json.response??$json);
const correctionSignal=/\b(?:actually|correction|correct|change|update|instead)\b|(?:تصحيح|تعديل|غير|غيّر|لا قصدي|قصدي)/i.test(msg);
const records=[];
const seen=new Set();
const singleValueIndex=new Map();
const multiValueEntities=new Set(['subjects','grades']);

function add(name,rawValue,confidence=0.8,source='customer'){
 if(!schema.has(name)||rawValue===undefined||rawValue===null||rawValue==='')return;
 const key=name+'|'+JSON.stringify(rawValue);
 if(seen.has(key))return; seen.add(key);
 const row=schema.get(name);
 const canonical=normalize(name,rawValue);
 const rec={entity:name,raw:rawValue,canonical,confidence:Math.max(0,Math.min(1,Number(confidence)||0.8)),source,status:validStatus(name,canonical,row),sensitivity:row.sensitivity||null,is_correction:Boolean(raw.correction_detected||correctionSignal)};
 if(!multiValueEntities.has(name) && singleValueIndex.has(name)){
   const idx=singleValueIndex.get(name);
   if(rec.confidence > Number(records[idx]?.confidence||0)) records[idx]=rec;
   return;
 }
 records.push(rec);
 if(!multiValueEntities.has(name)) singleValueIndex.set(name,records.length-1);
}

if(Array.isArray(raw.entities)){
 for(const e of raw.entities){ if(e&&typeof e==='object')add(clean(e.entity),e.raw,e.confidence,'customer'); }
}

// Deterministic recovery from CURRENT MESSAGE only.
const email=msg.match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/); if(email)add('email',email[0],0.99,'customer_deterministic');
const phone=msg.match(/\+?\d[\d\s().-]{6,}\d/); if(phone)add('phone',phone[0],0.95,'customer_deterministic');
const tz=msg.match(/\b(?:America|Canada|Europe|Asia|Africa)\/[A-Za-z0-9_+\-]+\b/); if(tz)add('timezone',tz[0],0.99,'customer_deterministic');
const grade=arabicDigits(msg).match(/(?:grade|gr|g|الصف|صف)\s*(?:الـ)?\s*(1[0-2]|[1-9])/i); if(grade)add('grade',grade[1],0.95,'customer_deterministic');
const subjectMap=[['Math',/رياضيات|ماث|\bmaths?\b|\bmathematics\b/i],['English',/اللغة الإنجليزية|اللغه الانجليزيه|\benglish\b/i],['French',/اللغة الفرنسية|اللغه الفرنسيه|\bfrench\b/i],['Physics',/فيزياء|\bphysics\b/i],['Chemistry',/كيمياء|\bchemistry\b/i],['Science',/علوم|\bscience\b/i],['Arabic',/اللغة العربية|اللغه العربيه|\barabic\b/i]];
